// ==============================================================================
// 7. HELPER ICON ACCESSORS
// ==============================================================================
inline const unsigned char* getActionIcon(int actionIdx) {
  switch (actionIdx) {
    case 0: return ICON_WALK_FWD;
    case 1: return ICON_WALK_REV;
    case 2: return ICON_TURN_LEFT;
    case 3: return ICON_TURN_RIGHT;
    case 4: return ICON_PUNCH;
    case 5: return ICON_PUSHUPS;
    case 6: return ICON_WAVE;
    default: return ICON_WALK_FWD;
  }
}

inline const unsigned char* getGearIcon(int rcGear) {
  return (rcGear == 1) ? ICON_GEAR_STRAFE : ICON_GEAR_DRIVE;
}

inline const unsigned char* getStuntIcon(int stuntIdx) {
  switch (stuntIdx) {
    case 0: return ICON_PUNCH;           // 01: Left Punch
    case 1: return ICON_PUNCH;           // 02: Right Punch
    case 2: return ICON_STUNT_BURST;     // 03: Single Kick (stays unchanged)
    case 3: return ICON_WAVE;            // 04: Wave Hand
    case 4: return ICON_STUNT_CELEBRATE; // 05: Celebrate
    case 5: return ICON_STUNT_KUNGFU;    // 06: Kung Fu
    case 6: return ICON_PUSHUPS;         // 07: Push-ups
    case 7: return ICON_PUSHUPS;         // 08: Squats
    case 8: return ICON_STUNT_BURST;     // 09: Handstand (stays unchanged)
    case 9: return ICON_STUNT_DANCE;     // 10: Dance
    default: return ICON_STUNT_BURST;
  }
}

inline const unsigned char* getJointGroupIcon(int groupIdx) {
  switch (groupIdx) {
    case 0: return ICON_BODY_HEAD;
    case 1: return ICON_BODY_L_ARM;
    case 2: return ICON_BODY_R_ARM;
    case 3: return ICON_BODY_L_LEG;
    case 4: return ICON_BODY_R_LEG;
    default: return ICON_BODY_HEAD;
  }
}

inline const unsigned char* getModeBadgeIcon(int modeIdx) {
  switch (modeIdx) {
    case 0: return ICON_MODE_BLOCKS;
    case 1: return ICON_MODE_GAMEPAD;
    case 2: return ICON_MODE_HUMANOID;
    default: return ICON_MODE_BLOCKS;
  }
}

inline const unsigned char* getBleIcon(bool connected) {
  return connected ? ICON_BLE_CONNECTED : ICON_BLE_DISCONNECTED;
}

inline const unsigned char* getBatteryIcon(int percent, bool charging = false) {
  if (charging) return ICON_BATTERY_CHARGING;
  if (percent > 70) return ICON_BATTERY_FULL;
  if (percent > 30) return ICON_BATTERY_MEDIUM;
  if (percent > 10) return ICON_BATTERY_LOW;
  return ICON_BATTERY_WARNING;
}
